def a_romano(n):
    valores = [
        1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1
    ]
    simbolos = [
        "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"
    ]
    resultado = ""
    for i in range(len(valores)):
        while n >= valores[i]:
            resultado += simbolos[i]
            n -= valores[i]
    return resultado

def from_romano(s):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    integer_value = 0
    prev_value = 0
    for char in s:
        current_value = roman_map[char]
        if current_value < prev_value:
            integer_value -= current_value
        else:
            integer_value += current_value
        prev_value = current_value
    return integer_value

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = (lista[0], 1)
    actual_racha = (lista[0], 1)

    for i in range(1, len(lista)):
        if lista[i] == lista[i-1]:
            elemento, longitud = actual_racha
            actual_racha = (elemento, longitud + 1)
        else:
            if actual_racha[1] > max_racha[1]:
                max_racha = actual_racha
            actual_racha = (lista[i], 1)

    # Comprobar la última racha
    if actual_racha[1] > max_racha[1]:
        return actual_racha
    else:
        return max_racha

