def fusionar(intervalos):
    if not intervalos:
        return []

    intervalos.sort(key=lambda x: x[0])

    unidos = [intervalos[0]]

    for i in range(1, len(intervalos)):
        actual = intervalos[i]
        ultimo_unido = unidos[-1]

        # Si el inicio del intervalo actual es menor o igual al fin del último unido, se fusionan
        if actual[0] <= ultimo_unido[1]:
            nuevo_fin = max(ultimo_unido[1], actual[1])
            unidos[-1] = (ultimo_unido[0], nuevo_fin)
        else:
            unidos.append(actual)

    return unidos

