    current_char = s[0]

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            compressed.append(current_char + str(count))
            current_char = s[i]
            count = 1

    compressed.append(current_char + str(count))

    compressed_string = "".join(compressed)

    if len(compressed_string) < len(s):
        return compressed_string
    else:
        return s

