def contar_islas(grid):
    rows = len(grid)
    if rows == 0:
        return 0
    cols = len(grid[0])
    count = 0

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == 0:
            return
        grid[r][c] = 0  # Marcar como visitado
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                count += 1
                dfs(r, c)
    return count

def distancia(a, b):
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,        # Borrar
                dp[i][j - 1] + 1,        # Insertar
                dp[i - 1][j - 1] + cost  # Sustituir o coincidir
            )

    return dp[m][n]

import re

def validar_password(p):
    if len(p) < 8:
        return False
    if not re.search(r"[A-Z]", p):
        return False
    if not re.search(r"[a-z]", p):
        return False
    if not re.search(r"\d", p):
        return False
    if not re.search(r"[^a-zA-Z0-9]", p):
        return False
    return True

def a_base(n, base):
    if n == 0:
        return '0'

    caracteres = "0123456789abcdef"
    resultado = ""

    while n > 0:
        resto = n % base
        resultado = caracteres[resto] + resultado
        n //= base

    return resultado

def interseccion(a, b):
    resultado = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            resultado.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return resultado

