def sumar_romanos(a, b):
    ROMAN_MAP = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    ROMAN_SYMBOLS = ['I', 'V', 'X', 'L', 'C', 'D', 'M']

    def roman_to_int(s):
        total = 0
        for i in range(len(s)):
            value = ROMAN_MAP[s[i]]
            if i > 0 and ROMAN_MAP[s[i-1]] > value:
                total -= value
            else:
                total += value
        return total

    def int_to_roman(num):
        if not (1 <= num <= 3999):
            raise ValueError("Número fuera del rango válido (1-3999)")

        mapping = {
            1000: 'M', 900: 'CM', 500: 'D', 400: 'CD', 100: 'C', 90: 'XC', 50: 'L', 40: 'XL', 10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'
        }

        result = ""
        sorted_values = sorted(mapping.keys(), reverse=True)

        for value in sorted_values:
            while num >= value:
                result += mapping[value]
                num -= value
        return result

    num_a = roman_to_int(a)
    num_b = roman_to_int(b)

    suma = num_a + num_b

    return int_to_roman(suma)

